  "us-cs-caltech": { status: "verified", source: "https://www.admissions.caltech.edu/apply/first-year-applicants/standardized-tests", checkedDate: "2026-07-03", notes: "Re-checked 2026-07-03 specifically for newly published enrolled SAT/ACT middle-50% ranges. Result: still NOT published by Caltech. (1) The most recent Common Data Set indexed on Caltech's Institutional Research Office site (iro.caltech.edu) is the 2024-2025 CDS (published May 2025), covering the Fall 2024 entering class, which was admitted under the test-blind policy — no 2025-2026 CDS exists yet. (2) No official Class of 2029 profile with SAT/ACT ranges was found on any caltech.edu domain; caltech.edu-restricted searches for the class profile surface only stale pre-2021 content (it still lists SAT Subject Test ranges, discontinued 2021), so figures like '1520-1570' returned by search engines from admissions.caltech.edu are from an old pre-test-blind cohort, not the reinstated-test classes. (3) Prep-blog claims of a Class of 2029 range (e.g. 1540-1580) were found but are not acceptable sources and were NOT recorded. Test requirement (reinstated with the April 2024 announcement, first applying to the 2024-25 application cycle) reconfirmed via the official standardized-tests page and Caltech news release. Holistic admissions, no published grade cutoffs — confirmed. SAT/ACT ranges remain null: not published by the university as of 2026-07-03; verified-with-null per resolution rules since everything Caltech does publish is confirmed. Expect ranges in the 2025-2026 CDS or an updated class profile once the first test-required cohort's data is released." },
  "us-physics-caltech": { status: "verified", source: "https://www.admissions.caltech.edu/apply/first-year-applicants/standardized-tests", checkedDate: "2026-07-03", notes: "Re-checked 2026-07-03 for newly published enrolled SAT/ACT ranges — still NOT published by Caltech. Latest CDS on iro.caltech.edu is 2024-2025 (May 2025, covers the test-blind Fall 2024 entering class); no 2025-2026 CDS or Class of 2029 score profile exists on any caltech.edu domain. Indexed admissions.caltech.edu class-profile content is stale pre-2021 data (still shows discontinued SAT Subject Test ranges), so any '1520-1570'-type figures attributed to that page are from an old pre-test-blind cohort and were not recorded. Prep-blog Class-of-2029 ranges (1540-1580 etc.) ignored per rules. Test requirement and holistic no-cutoff admissions reconfirmed against official pages. SAT/ACT stay null: not published by the university as of 2026-07-03; verified-with-null since everything Caltech does publish is confirmed." },
