  "Princeton University":                { test: "optional",    sat: "1500–1560", act: "34–35" },
  "Stanford University":                 { test: "required",    sat: "1510–1570", act: "34–35" },
  "Columbia University":                 { test: "optional",    sat: "1510–1560", act: "34–35" },
