  "Cornell University":                  { test: "required",    sat: "1510–1560", act: "33–35" },
  "Carnegie Mellon University":          { test: "varies",      sat: "1510–1560", act: "33–35" },
  "UC Berkeley":                         { test: "blind",       sat: null,        act: null },
  "University of Michigan":              { test: "optional",    sat: "1360–1530", act: "31–34" },
  "New York University":                 { test: "optional",    sat: "1480–1550", act: "33–35" },
  "Georgetown University":               { test: "required",    sat: "1400–1540", act: "31–35" },
  "Duke University":                     { test: "optional",    sat: "1520–1570", act: "34–35" },
  "Johns Hopkins University":            { test: "required",    sat: "1530–1560", act: "34–36" },
  "Northwestern University":             { test: "optional",    sat: "1510–1560", act: "34–35" },
  "Dartmouth College":                   { test: "required",    sat: "1440–1560", act: "33–35" },
  "Brown University":                    { test: "required",    sat: "1510–1560", act: "34–35" },
  "Rice University":                     { test: "recommended", sat: "1510–1560", act: "34–35" },
  "Vanderbilt University":               { test: "optional",    sat: "1510–1560", act: "34–35" },
  "University of Notre Dame":            { test: "optional",    sat: "1470–1540", act: "33–35" },
  "Washington University in St. Louis":  { test: "optional",    sat: "1500–1570", act: "33–35" },
  "Emory University":                    { test: "optional",    sat: "1480–1540", act: "32–35" },
  "UCLA":                                { test: "blind",       sat: null,        act: null },
  "University of Southern California":   { test: "optional",    sat: "1450–1550", act: "32–35" },
  "Georgia Tech":                        { test: "required",    sat: "1370–1530", act: "30–34" },
  "University of Virginia":              { test: "optional",    sat: "1410–1520", act: "32–35" },
  "University of Illinois Urbana-Champaign": { test: "optional", sat: "1390–1520", act: "30–34" },
  "Purdue University":                   { test: "required",    sat: "1220–1480", act: "28–34" },
